import{_ as l,l as n,o as e,c as o,v as i,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"线性一致性","description":"","frontmatter":{"title":"线性一致性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linearizability.md","filePath":"cs/linearizability.md","lastUpdated":1789023840000}'),h={name:"cs/linearizability.md"};function E(_,a,A,m,u,f){const t=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="线性一致性" tabindex="-1">线性一致性 <a class="header-anchor" href="#线性一致性" aria-label="Permalink to &quot;线性一致性&quot;">​</a></h1><div class="epigraph"><p>每次操作像在调用与返回之间的某个瞬间原子生效，且该顺序符合实时先后。客户端不必知道副本。</p><footer>—— 据 Herlihy and Wing, Linearizability: A Correctness Condition for Concurrent Objects, TOPLAS 1990 整理</footer></div><p>上一课<a href="/cs/byzantine-generals">拜占庭将军</a>封上时间与失败课序。本单元不重写 \\(n\\gt 3f\\)。缺口是<strong>对象看起来像什么</strong>：多副本、多客户端时，「一次写」何时变成大家读到的值。本课钉线性一致（linearizability），后课再放松到顺序、因果、最终。后课默认已经读完：强一致首先指这个实时+原子点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>并发对象有历史：调用与响应事件。线性一致：存在每个操作的线性化点，落在区间内，生效顺序是合法的单对象顺序，且实时不重叠的操作保持先后。比顺序一致强：顺序一致允许把整个历史重排，只要每客户端程序序还在，不必尊重跨客户端的实时。</p><p>缺口不是再讲锁，而是把「像单机原子变量」写成历史性质。寄存器的读写、队列的 enq/deq 都适用。分布式里：多数派读/写、主备切换后的读，都要问是否还能找到线性化点。</p><p><span class="marginnote">Herlihy–Wing 强调局部性：系统线性一致当且仅当每个对象各自线性一致。组合比顺序一致容易。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>证明或测试：给历史找线性化点，或用线性化点搜索（Jepsen/Knossos、Porcupine）。实现：单主串行化所有操作；或共识日志；或法定人数交叠。本课不写 Paxos 消息。</p>',9)),(e(),s(c,null,{default:r(()=>[p(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E8%B0%83%E7%94%A8%22%5D%20--%3E%20LP%5B%22%E7%BA%BF%E6%80%A7%E5%8C%96%E7%82%B9%22%5D%0A%20%20LP%20--%3E%20RESP%5B%22%E8%BF%94%E5%9B%9E%22%5D%0A%20%20REAL%5B%22%E5%AE%9E%E6%97%B6%E5%85%88%E5%90%8E%22%5D%20--%3E%20ORD%5B%22%E7%BA%BF%E6%80%A7%E5%8C%96%E9%A1%BA%E5%BA%8F%22%5D%0A%20%20SEQ%5B%22%E5%90%88%E6%B3%95%E5%AF%B9%E8%B1%A1%E8%AF%AD%E4%B9%89%22%5D%20--%3E%20ORD%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>与<a href="/cs/failure-models">故障模型</a>：崩溃恢复后若读到旧主未刷的值，线性化点就不存在——那是主备课的缺口。本课只给尺子。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线性一致禁止「读到未来」也禁止「实时上更晚的读读到更旧的值」（在中间没有写的情况下）。stale read、从从库读，默认不是线性一致，除非从库的 apply 位置被读请求等到。时钟：线性化点是逻辑上的，不必是 NTP 瞬间；TrueTime 用 \\(\\varepsilon\\) 把点钉在墙钟区间里，那是后课。</p><p>本课不把线性一致与可串行混名：可串行是事务调度，线性一致是单个对象（或已声明为对象的组合）的实时原子。事务隔离课已经用冲突图；这里对象是寄存器、锁、配置。</p><p>局部性让你分开证锁服务与文件服务。顺序一致没有局部性，组合会破。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义会话保证，不写 CAP。不把「强一致」广告词当定理。后课默认：要实时+原子，就线性一致；只要每客户端程序序，是顺序一致；只要因果，是下一课的另一档。拜占庭下线性一致仍有定义，实现更贵。</p><p>尺子先于协议。后面每一种复制都要回答：它保这把尺子的哪一段。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线性化点落在调用–返回之间，且尊重实时先后。</li><li>局部性：逐对象证即可组合。</li><li>从库读、缓存、异步复制默认不是线性一致。</li><li>出处：Herlihy and Wing, TOPLAS 1990。</li></ul>',10))])}const P=l(h,[["render",E]]);export{b as __pageData,P as default};
